pub fn architecture_contract_schema_hash(contract_id: &str) -> Option<&'static str> {
    ARCHITECTURE_CONTRACT_SCHEMA_HASHES
        .iter()
        .find_map(|(id, hash)| (*id == contract_id).then_some(*hash))
}

